#!/usr/bin/env bash
# Bash completion script for bpl CLI.
# Generated by scripts/generate_completions.ts from the CLI's command
# definitions; do not edit by hand.
# Installation:
#   1. Copy this file to /etc/bash_completion.d/bpl or ~/.local/share/bash-completion/completions/bpl
#   2. Or source it in your ~/.bashrc: source /path/to/bpl-completion.bash
#   3. Or run: bpl completion bash > ~/.local/share/bash-completion/completions/bpl

_bpl_completion() {
    local cur prev word match i command="" sub=""
    COMPREPLY=()
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"

    local commands="run run-script rs dev build check format lint pack install lock list init uninstall remove package-cache completion docs new clean bindgen doctor help"

    # Values of options that take one
    case "${prev}" in
        -e|--eval|--cpu|--march|--clang-flag|-l|--lib|-j|--jobs|-O|--indent-width|--package-version)
            return 0
            ;;
        -o|--output|--debug-ir-path|--header|--stdin-filepath|--config)
            while IFS= read -r match; do COMPREPLY+=("$match"); done < <(compgen -f -- "${cur}")
            return 0
            ;;
        --emit)
            COMPREPLY=( $(compgen -W "llvm ast tokens formatted" -- "${cur}") )
            return 0
            ;;
        --target)
            COMPREPLY=( $(compgen -W "x86_64-pc-linux-gnu aarch64-unknown-linux-gnu arm64-apple-darwin x86_64-apple-darwin x86_64-pc-windows-gnu wasm32-unknown-unknown wasm32-wasi" -- "${cur}") )
            return 0
            ;;
        --sysroot|-L|--lib-path)
            COMPREPLY=( $(compgen -d -- "${cur}") )
            return 0
            ;;
        --wasm-runtime)
            COMPREPLY=( $(compgen -W "freestanding host" -- "${cur}") )
            return 0
            ;;
        --object)
            COMPREPLY=( $(compgen -f -X '!*.@(o|ll|bc)' -- "${cur}") )
            return 0
            ;;
        --line-ending)
            COMPREPLY=( $(compgen -W "lf crlf" -- "${cur}") )
            return 0
            ;;
        --template)
            COMPREPLY=( $(compgen -W "app library" -- "${cur}") )
            return 0
            ;;
    esac

    # The command (and package-cache style subcommand) typed so far
    for ((i=1; i<COMP_CWORD; i++)); do
        word="${COMP_WORDS[i]}"
        if [[ -z "$command" ]]; then
            if [[ " $commands " == *" $word "* ]]; then
                command="$word"
            fi
        elif [[ -z "$sub" ]]; then
            case "$command" in
            package-cache) [[ " list verify clean repair " == *" $word "* ]] && sub="$word" ;;
            esac
        fi
    done

    case "$command" in
        run)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "--project -o --output -v --verbose -q --quiet -O --debug --debug-ir-path --time --cache -j --jobs -l --lib -L --lib-path --object --clang-flag --no-prelude --color --no-color -h --help" -- "${cur}") )
                return 0
            fi
            while IFS= read -r match; do COMPREPLY+=("$match"); done < <(compgen -f -- "${cur}")
            return 0
            ;;
        run-script|rs)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "--list --json -h --help" -- "${cur}") )
                return 0
            fi
            return 0
            ;;
        dev)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "-v --verbose -q --quiet --clear --no-run -O --debug --debug-ir-path --time --cache --cache-stats --no-prelude --color --no-color -h --help" -- "${cur}") )
                return 0
            fi
            while IFS= read -r match; do COMPREPLY+=("$match"); done < <(compgen -f -- "${cur}")
            return 0
            ;;
        build)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "-o --output --shared --header --emit --project -v --verbose -q --quiet -O --debug --time --target --sysroot --cpu --march --clang-flag --wasm-runtime --debug-ir-path -l --lib -L --lib-path --object --cache --cache-stats -j --jobs --no-prelude --color --no-color --json -h --help" -- "${cur}") )
                return 0
            fi
            while IFS= read -r match; do COMPREPLY+=("$match"); done < <(compgen -f -- "${cur}")
            return 0
            ;;
        check)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "-v --verbose -q --quiet --json --time --no-prelude --color --no-color -h --help" -- "${cur}") )
                return 0
            fi
            while IFS= read -r match; do
                if [[ -d "$match" || "$match" == *.bpl || "$match" == *.x ]]; then
                    COMPREPLY+=("$match")
                fi
            done < <(compgen -f -- "${cur}")
            return 0
            ;;
        format)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "--stdin-filepath -w --write --check --config --no-config --indent-width --use-tabs --no-use-tabs --line-ending -v --verbose --json -h --help" -- "${cur}") )
                return 0
            fi
            while IFS= read -r match; do
                if [[ -d "$match" || "$match" == *.bpl || "$match" == *.x ]]; then
                    COMPREPLY+=("$match")
                fi
            done < <(compgen -f -- "${cur}")
            return 0
            ;;
        lint)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "--stdin-filepath -v --verbose --no-fail-on-warnings --json -h --help" -- "${cur}") )
                return 0
            fi
            while IFS= read -r match; do
                if [[ -d "$match" || "$match" == *.bpl || "$match" == *.x ]]; then
                    COMPREPLY+=("$match")
                fi
            done < <(compgen -f -- "${cur}")
            return 0
            ;;
        pack)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "-o --output --json -h --help" -- "${cur}") )
                return 0
            fi
            return 0
            ;;
        install)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "-g --global -v --verbose --locked --update --repair-lock --json -h --help" -- "${cur}") )
                return 0
            fi
            while IFS= read -r match; do COMPREPLY+=("$match"); done < <(compgen -f -- "${cur}")
            return 0
            ;;
        lock)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "-v --verbose --json -h --help" -- "${cur}") )
                return 0
            fi
            return 0
            ;;
        list)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "-g --global --tree --json -h --help" -- "${cur}") )
                return 0
            fi
            return 0
            ;;
        init)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "--json -h --help" -- "${cur}") )
                return 0
            fi
            return 0
            ;;
        uninstall|remove)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "-g --global --json -h --help" -- "${cur}") )
                return 0
            fi
            return 0
            ;;
        package-cache)
            if [[ -z "$sub" ]]; then
                if [[ "$cur" == -* ]]; then
                    COMPREPLY=( $(compgen -W "-h --help" -- "${cur}") )
                else
                    COMPREPLY=( $(compgen -W "list verify clean repair" -- "${cur}") )
                fi
                return 0
            fi
            case "$sub" in
                list)
                    COMPREPLY=( $(compgen -W "--json -h --help" -- "${cur}") )
                    return 0
                    ;;
                verify)
                    COMPREPLY=( $(compgen -W "--json -h --help" -- "${cur}") )
                    return 0
                    ;;
                clean)
                    COMPREPLY=( $(compgen -W "--package-version --dry-run --json -h --help" -- "${cur}") )
                    return 0
                    ;;
                repair)
                    COMPREPLY=( $(compgen -W "--package-version --dry-run --json -h --help" -- "${cur}") )
                    return 0
                    ;;
            esac
            return 0
            ;;
        completion)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "--json -h --help" -- "${cur}") )
                return 0
            fi
            COMPREPLY=( $(compgen -W "bash zsh" -- "${cur}") )
            return 0
            ;;
        docs)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "-o --output --force --public-only --json -h --help" -- "${cur}") )
                return 0
            fi
            while IFS= read -r match; do COMPREPLY+=("$match"); done < <(compgen -f -- "${cur}")
            return 0
            ;;
        new)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "--template -v --verbose --no-git --json -h --help" -- "${cur}") )
                return 0
            fi
            return 0
            ;;
        clean)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "-v --verbose --dry-run --json -h --help" -- "${cur}") )
                return 0
            fi
            return 0
            ;;
        bindgen)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "-o --output --json -h --help" -- "${cur}") )
                return 0
            fi
            while IFS= read -r match; do COMPREPLY+=("$match"); done < <(compgen -f -- "${cur}")
            return 0
            ;;
        doctor)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "--json -h --help" -- "${cur}") )
                return 0
            fi
            COMPREPLY=( $(compgen -W "packages sanitizer" -- "${cur}") )
            return 0
            ;;
        help)
            if [[ "$cur" == -* ]]; then
                COMPREPLY=( $(compgen -W "" -- "${cur}") )
                return 0
            fi
            COMPREPLY=( $(compgen -W "${commands}" -- "${cur}") )
            return 0
            ;;
    esac

    # No command yet: root options, commands, or source files
    if [[ "$cur" == -* ]]; then
        COMPREPLY=( $(compgen -W "-e --eval --stdin -o --output --emit -d --dwarf --target --sysroot --cpu --march --clang-flag --wasm-runtime --debug-ir-path -l --lib -L --lib-path --object -v --verbose -q --quiet --cache --cache-stats -j --jobs --no-prelude -O --debug --time --json --color --no-color -V --version -h --help" -- "${cur}") )
    else
        COMPREPLY=( $(compgen -W "${commands}" -- "${cur}") )
        while IFS= read -r match; do
            if [[ -d "$match" || "$match" == *.bpl || "$match" == *.x ]]; then
                COMPREPLY+=("$match")
            fi
        done < <(compgen -f -- "${cur}")
    fi
    return 0
}

# Register the completion function
complete -o filenames -F _bpl_completion bpl
